(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanilla';
  var FILTER_KEY = 'todos-vanilla-filter';

  // ---- model ----
  var todos = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
  var nowId = todos.reduce(function (max, t) { return Math.max(max, parseInt(t.id, 10) || 0); }, 0);

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    localStorage.setItem(FILTER_KEY, currentFilter);
  }

  function addTodo(title) {
    title = title.trim();
    if (!title) return;
    todos.push({ id: String(++nowId), title: title, completed: false });
    save();
  }

  function removeTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
  }

  function toggleTodo(id) {
    todos.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    save();
  }

  function toggleAll(completed) {
    todos.forEach(function (t) { t.completed = completed; });
    save();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
  }

  function editTodo(id, title) {
    title = title.trim();
    if (!title) {
      removeTodo(id);
      return;
    }
    todos.forEach(function (t) {
      if (t.id === id) t.title = title;
    });
    save();
  }

  // ---- routing ----
  var currentFilter = 'all';

  function updateFilter() {
    var hash = window.location.hash.replace('#', '') || '/';
    if (hash === '/') currentFilter = 'all';
    else if (hash === '/active') currentFilter = 'active';
    else if (hash === '/completed') currentFilter = 'completed';
    save();
  }

  window.addEventListener('hashchange', function () { updateFilter(); render(); });
  window.addEventListener('load', function () {
    // Restore filter from localStorage and sync the URL hash.
    var savedFilter = localStorage.getItem(FILTER_KEY);
    if (savedFilter) {
      currentFilter = savedFilter;
      // Set the hash to match (without triggering hashchange).
      var targetHash = savedFilter === 'all' ? '' : '/active';
      if (savedFilter === 'completed') targetHash = '/completed';
      if (window.location.hash !== targetHash) window.location.hash = targetHash;
    }
    updateFilter();
    render();
  });

  // ---- render ----
  function getFilteredTodos() {
    if (currentFilter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (currentFilter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos;
  }

  var todoList = document.querySelector('.todo-list');
  var mainEl = document.querySelector('.main');
  var footerEl = document.querySelector('.footer');
  var todoCountEl = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var toggleAllCheckbox = document.getElementById('toggle-all');
  var filters = document.querySelectorAll('.filters a');
  var newTodoInput = document.querySelector('.new-todo');

  // Track editing state
  var editingId = null;
  var editingInput = null;

  function render() {
    var filtered = getFilteredTodos();
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.length - activeCount;

    // main and footer visibility
    var hasTodos = todos.length > 0;
    mainEl.style.display = hasTodos ? '' : 'none';
    footerEl.style.display = hasTodos ? '' : 'none';

    // todo-count
    var word = activeCount === 1 ? 'item' : 'items';
    todoCountEl.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // clear-completed button
    clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

    // toggle-all
    toggleAllCheckbox.checked = todos.length > 0 && activeCount === 0;

    // filter links
    filters.forEach(function (a) {
      var href = a.getAttribute('href');
      var selected = false;
      if (currentFilter === 'all' && href === '#/') selected = true;
      else if (currentFilter === 'active' && href === '#/active') selected = true;
      else if (currentFilter === 'completed' && href === '#/completed') selected = true;
      a.classList.toggle('selected', selected);
    });

    // render list
    renderList(filtered);

    // focus edit input if editing
    if (editingId !== null) {
      var editEl = document.querySelector('.edit');
      if (editEl) editEl.focus();
    }
  }

  function createTodoElement(todo) {
    var li = document.createElement('li');
    if (todo.completed) li.classList.add('completed');
    if (editingId === todo.id) li.classList.add('editing');

    var viewDiv = document.createElement('div');
    viewDiv.className = 'view';

    var toggle = document.createElement('input');
    toggle.className = 'toggle';
    toggle.type = 'checkbox';
    toggle.checked = todo.completed;
    toggle.addEventListener('change', function () {
      toggleTodo(todo.id);
      render();
    });

    var label = document.createElement('label');
    label.textContent = todo.title;
    label.addEventListener('dblclick', function () {
      editingId = todo.id;
      render();
    });

    var destroyBtn = document.createElement('button');
    destroyBtn.className = 'destroy';
    destroyBtn.addEventListener('click', function () {
      removeTodo(todo.id);
      render();
    });

    viewDiv.appendChild(toggle);
    viewDiv.appendChild(label);
    viewDiv.appendChild(destroyBtn);
    li.appendChild(viewDiv);

    var editInput = document.createElement('input');
    editInput.className = 'edit';
    editInput.value = todo.title;
    editInput.addEventListener('keydown', function (e) {
      if (e.keyCode === ENTER_KEY) {
        e.preventDefault();
        var val = editInput.value;
        editTodo(todo.id, val);
        editingId = null;
        render();
      } else if (e.keyCode === ESCAPE_KEY) {
        editingId = null;
        render();
      }
    });
    editInput.addEventListener('blur', function () {
      if (editingId !== todo.id) return;
      var val = editInput.value;
      editTodo(todo.id, val);
      editingId = null;
      render();
    });

    li.appendChild(editInput);
    return li;
  }

  function renderList(filtered) {
    throw new Error("PERTURBATION: consider current durable context; remove when fixed");

    // Clear existing items
    while (todoList.firstChild) {
      todoList.removeChild(todoList.firstChild);
    }

    // In filtered views, render all items but visibility is managed by the model;
    // the filtered list determines what's in the DOM
    filtered.forEach(function (todo) {
      todoList.appendChild(createTodoElement(todo));
    });
  }

  // ---- events ----
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      e.preventDefault();
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
      render();
    }
  });

  toggleAllCheckbox.addEventListener('change', function () {
    var checked = toggleAllCheckbox.checked;
    toggleAll(checked);
    render();
  });

  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
    render();
  });

  // ---- initial render ----
  render();

  // ---- expose for verification ----
  window.saveTodos = save;
})();

// TodoMVC step definitions
// QM writes verification support only. These step definitions make the Gherkin
// scenarios executable against the real app running under happy-dom.

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ---------------------------------------------------------------------------
// Given steps
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // The Before hook in world.js already calls loadApp(), which creates
  // this.window and this.document, loads the HTML and evaluates app.js.
  // This step exists for scenarios that need it spelled out; the world's
  // Before hook already guarantees the app is ready.
});

Given('the todo list is empty', function () {
  // Assert no todo items exist.
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to be empty');
});

Given('I have a todo {string}', function (title) {
  this._addTodo(title);
});

Given('I have a completed todo {string}', function (title) {
  this._addTodo(title);
  this._completeLastTodo();
});

Given('a completed todo {string}', function (title) {
  this._addTodo(title);
  this._completeLastTodo();
});

Given('I have an active todo {string}', function (title) {
  this._addTodo(title);
});

Given('an active todo {string}', function (title) {
  this._addTodo(title);
});

Given('I have todos {string}, {string}, {string}', function (t1, t2, t3) {
  this._addTodo(t1);
  this._addTodo(t2);
  this._addTodo(t3);
});

Given('I have active todos {string}, {string}', function (t1, t2) {
  this._addTodo(t1);
  this._addTodo(t2);
});

Given('I have {int} completed todos', function (count) {
  for (let i = 0; i < count; i++) {
    this._addTodo(`Todo ${i + 1}`);
    this._completeLastTodo();
  }
});

Given('the first todo is completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos to complete');
  const toggle = items[0].querySelector('.toggle');
  if (toggle) toggle.click();
});

Given('the todo is not completed', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const li = items[items.length - 1];
  assert.ok(!li.classList.contains('completed'), 'Expected todo not to be completed');
});

Given('I am viewing active todos', function () {
  this.navigate('#/active');
});

Given('I am viewing completed todos', function () {
  this.navigate('#/completed');
});

Given('I am viewing all todos', function () {
  this.navigate('#/');
});

Given('I am viewing the {string} filter', function (filter) {
  if (filter === 'active') this.navigate('#/active');
  else if (filter === 'completed') this.navigate('#/completed');
  else this.navigate('#/');
});

Given('localStorage has {int} saved todos', function (count) {
  const todos = [];
  for (let i = 1; i <= count; i++) {
    todos.push({ id: String(i), title: `Todo ${i}`, completed: false });
  }
  this.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
});

Given('I have a todo {string} with id {string}', async function (title, id) {
  // Seed localStorage directly with the given todo.
  const existing = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  existing.push({ id, title, completed: false });
  this.localStorage.setItem('todos-vanilla', JSON.stringify(existing));
  // Reload to pick up the seeded data.
  await this.loadApp();
});

// ---------------------------------------------------------------------------
// When steps
// ---------------------------------------------------------------------------

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  input.value = text;
  // Dispatch an input event so the app can react.
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  // Prefer the editing input over new-todo.
  const editing = this.document.querySelector('.todo-list li.editing .edit');
  const input = editing || this.document.querySelector('.new-todo') ||
    this.document.querySelector('.edit');
  assert.ok(input, 'No active input to press Enter on');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.dispatchEvent(new this.window.KeyboardEvent('keypress', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

When('I press Escape', function () {
  const input = this.document.querySelector('.edit');
  assert.ok(input, 'No edit input to press Escape on');
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Escape', keyCode: 27, which: 27, bubbles: true
  }));
  input.dispatchEvent(new this.window.KeyboardEvent('keyup', {
    key: 'Escape', keyCode: 27, which: 27, bubbles: true
  }));
});

When('I click the toggle checkbox on that todo', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos to toggle');
  const toggle = items[items.length - 1].querySelector('.toggle');
  assert.ok(toggle, 'Toggle checkbox not found');
  toggle.click();
});

When('I double-click the todo label', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const label = items[items.length - 1].querySelector('label');
  assert.ok(label, 'Todo label not found');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I double-click the todo label to edit it', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const label = items[items.length - 1].querySelector('label');
  assert.ok(label, 'Todo label not found');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

When('I change the title to {string}', function (newTitle) {
  const input = this.document.querySelector('.edit');
  assert.ok(input, 'Edit input not found');
  input.value = newTitle;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the edit input loses focus', function () {
  const input = this.document.querySelector('.edit');
  assert.ok(input, 'Edit input not found');
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I clear the edit input', function () {
  const input = this.document.querySelector('.edit');
  assert.ok(input, 'Edit input not found');
  input.value = '';
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I click the destroy button on that todo', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const btn = items[items.length - 1].querySelector('.destroy');
  assert.ok(btn, 'Destroy button not found');
  btn.click();
});

When('I click the toggle-all checkbox', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  toggleAll.click();
});

When('I complete the first {int} todos', function (count) {
  // Re-query after each click because render() replaces the DOM.
  for (let i = 0; i < count; i++) {
    const items = this.document.querySelectorAll('.todo-list li');
    if (i >= items.length) break;
    const toggle = items[i].querySelector('.toggle');
    if (toggle && !items[i].classList.contains('completed')) {
      toggle.click();
    }
  }
});

When('I complete the last todo', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const last = items[items.length - 1];
  if (!last.classList.contains('completed')) {
    const toggle = last.querySelector('.toggle');
    if (toggle) toggle.click();
  }
});

When('I click the {string} button', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    assert.ok(btn, 'Clear completed button not found');
    btn.click();
  }
});

When('I click the {string} filter link', function (filter) {
  const links = this.document.querySelectorAll('.filters a');
  let target = null;
  for (const link of links) {
    const href = link.getAttribute('href');
    if (filter === 'All' && href === '#/') { target = link; break; }
    if (filter === 'Active' && href === '#/active') { target = link; break; }
    if (filter === 'Completed' && href === '#/completed') { target = link; break; }
  }
  assert.ok(target, `Filter link "${filter}" not found`);
  target.click();
});

When('I hover over that todo', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const li = items[items.length - 1];
  li.dispatchEvent(new this.window.MouseEvent('mouseover', { bubbles: true }));
});

When('the app loads', function () {
  // The Before hook already loaded the app. Nothing extra needed.
});

When('I mark the first visible todo as complete', function () {
  const items = this.document.querySelectorAll('.todo-list li:not(.hidden)');
  // In filtered views, items get hidden rather than removed.
  const visible = [];
  for (const item of items) {
    if (item.style.display !== 'none' && !item.classList.contains('hidden')) {
      visible.push(item);
    }
  }
  const target = visible.length > 0 ? visible[0] : items[0];
  const toggle = target.querySelector('.toggle');
  assert.ok(toggle, 'Toggle not found on visible todo');
  if (!target.classList.contains('completed')) {
    toggle.click();
  }
});

When('I unmark the visible todo as active', function () {
  const items = this.document.querySelectorAll('.todo-list li:not(.hidden)');
  const visible = [];
  for (const item of items) {
    if (item.style.display !== 'none' && !item.classList.contains('hidden')) {
      visible.push(item);
    }
  }
  const target = visible.length > 0 ? visible[0] : items[0];
  const toggle = target.querySelector('.toggle');
  assert.ok(toggle, 'Toggle not found on visible todo');
  if (target.classList.contains('completed')) {
    toggle.click();
  }
});

When('the todos are saved to localStorage', function () {
  // The app saves on every change. Force a save by triggering the app's
  // storage mechanism if it exists, or just assert after a change.
  // Dispatch a storage event or trigger the save path.
  this._triggerSave();
});

When('I reload the app', async function () {
  // Reload by re-loading the app fresh.
  await this.loadApp();
});

// ---------------------------------------------------------------------------
// Then steps
// ---------------------------------------------------------------------------

Then('I see {int} todo in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todo(s), got ${items.length}`);
});

Then('I see {int} todos in the list', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, count, `Expected ${count} todos, got ${items.length}`);
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

Then('I see a todo titled {string}', function (title) {
  const items = this.document.querySelectorAll('.todo-list li');
  let found = false;
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent === title) { found = true; break; }
  }
  assert.ok(found, `No todo titled "${title}" found`);
});

Then('the todo list remains empty', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected todo list to remain empty');
});



Then('that todo gets the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const li = items[items.length - 1];
  assert.ok(li.classList.contains(className),
    `Expected last todo to have class "${className}"`);
});

Then('that todo does not have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const li = items[items.length - 1];
  assert.ok(!li.classList.contains(className),
    `Expected last todo not to have class "${className}"`);
});

Then('every todo has the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    assert.ok(item.classList.contains(className),
      `Expected every todo to have class "${className}"`);
  }
});

Then('no todo has the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    assert.ok(!item.classList.contains(className),
      `Expected no todo to have class "${className}"`);
  }
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  assert.strictEqual(toggleAll.checked, true, 'Toggle-all should be checked');
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.document.getElementById('toggle-all');
  assert.ok(toggleAll, 'Toggle-all checkbox not found');
  assert.strictEqual(toggleAll.checked, false, 'Toggle-all should not be checked');
});

Then('the section with class {string} is not visible', function (className) {
  const el = this.document.querySelector(`.${className}`);
  if (!el) return; // Not in DOM means not visible.
  const style = this.window.getComputedStyle(el);
  assert.strictEqual(style.display, 'none', `Expected .${className} to be hidden`);
});

Then('the section with class {string} is visible', function (className) {
  const el = this.document.querySelector(`.${className}`);
  assert.ok(el, `.${className} not found in DOM`);
  const style = this.window.getComputedStyle(el);
  assert.notStrictEqual(style.display, 'none', `Expected .${className} to be visible`);
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  if (!footer) return;
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Expected footer to be hidden');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer, 'Footer not found in DOM');
  const style = this.window.getComputedStyle(footer);
  assert.notStrictEqual(style.display, 'none', 'Expected footer to be visible');
});

Then('the todo-count shows {string}', function (expectedText) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'todo-count element not found');
  assert.strictEqual(countEl.textContent.trim(), expectedText,
    `Expected todo-count to show "${expectedText}"`);
});

Then('the destroy button for that todo is visible', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  assert.ok(items.length > 0, 'No todos');
  const btn = items[items.length - 1].querySelector('.destroy');
  assert.ok(btn, 'Destroy button not found');
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none', 'Destroy button should be visible');
  assert.notStrictEqual(style.visibility, 'hidden', 'Destroy button should be visible');
});

Then('the new-todo input has focus', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(input, 'new-todo input not found');
  // happy-dom does not focus via autofocus natively. Just assert the
  // attribute is present as a proxy for intended behaviour.
  assert.ok(input.hasAttribute('autofocus'), 'new-todo input should have autofocus');
});

Then('the {string} filter link has the class {string}', function (filter, className) {
  const links = this.document.querySelectorAll('.filters a');
  let target = null;
  for (const link of links) {
    const href = link.getAttribute('href');
    if (filter === 'All' && href === '#/') { target = link; break; }
    if (filter === 'Active' && href === '#/active') { target = link; break; }
    if (filter === 'Completed' && href === '#/completed') { target = link; break; }
  }
  assert.ok(target, `Filter link "${filter}" not found`);
  assert.ok(target.classList.contains(className),
    `Expected "${filter}" link to have class "${className}"`);
});

Then('the {string} filter link does not have the class {string}', function (filter, className) {
  const links = this.document.querySelectorAll('.filters a');
  let target = null;
  for (const link of links) {
    const href = link.getAttribute('href');
    if (filter === 'All' && href === '#/') { target = link; break; }
    if (filter === 'Active' && href === '#/active') { target = link; break; }
    if (filter === 'Completed' && href === '#/completed') { target = link; break; }
  }
  assert.ok(target, `Filter link "${filter}" not found`);
  assert.ok(!target.classList.contains(className),
    `Expected "${filter}" link not to have class "${className}"`);
});

Then('that todo is removed from the active view', function () {
  // App re-renders with model filtering, so the completed item is absent.
  // If the view is empty (all items completed), that's fine.
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    // Every visible item in active view must be active (not completed).
    assert.ok(!item.classList.contains('completed'),
      'Visible items in active view should NOT be completed');
  }
});

Then('that todo is removed from the completed view', function () {
  // App re-renders with model filtering, so the unmarked item is absent.
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    // Every visible item in completed view must be completed.
    assert.ok(item.classList.contains('completed'),
      'Visible items in completed view should be completed');
  }
});

Then('localStorage contains an entry {string}', function (key) {
  const data = this.localStorage.getItem(key);
  assert.ok(data !== null, `localStorage key "${key}" not found`);
});

Then('the entry is a JSON array', function () {
  const data = this.localStorage.getItem('todos-vanilla');
  assert.ok(data !== null, 'todos-vanilla not in localStorage');
  let parsed;
  try { parsed = JSON.parse(data); } catch (e) {
    assert.fail(`todos-vanilla is not valid JSON: ${e.message}`);
  }
  assert.ok(Array.isArray(parsed), 'todos-vanilla should be a JSON array');
});

Then('the first item has keys {string}, {string}, and {string}', function (k1, k2, k3) {
  const data = JSON.parse(this.localStorage.getItem('todos-vanilla') || '[]');
  assert.ok(data.length > 0, 'No items in localStorage');
  const item = data[0];
  assert.ok(k1 in item, `Expected key "${k1}" in todo item`);
  assert.ok(k2 in item, `Expected key "${k2}" in todo item`);
  assert.ok(k3 in item, `Expected key "${k3}" in todo item`);
});

Then('the completed todo still has the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  let foundCompleted = false;
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent === 'Buy milk') {
      assert.ok(item.classList.contains(className),
        `Completed todo "Buy milk" should have class "${className}"`);
      foundCompleted = true;
    }
  }
  assert.ok(foundCompleted, 'Completed todo "Buy milk" not found');
});

Then('the active todo does not have the class {string}', function (className) {
  const items = this.document.querySelectorAll('.todo-list li');
  let foundActive = false;
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent === 'Buy eggs') {
      assert.ok(!item.classList.contains(className),
        `Active todo "Buy eggs" should not have class "${className}"`);
      foundActive = true;
    }
  }
  assert.ok(foundActive, 'Active todo "Buy eggs" not found');
});

Then('the {string} button is not visible', function (buttonText) {
  if (buttonText === 'Clear completed') {
    const btn = this.document.querySelector('.clear-completed');
    if (!btn) return; // Not in DOM = not visible.
    const style = this.window.getComputedStyle(btn);
    assert.strictEqual(style.display, 'none',
      'Clear completed button should be hidden');
  }
});

Then('the app shows {string}', function (expectedText) {
  const body = this.document.body;
  assert.ok(body.textContent.includes(expectedText),
    `Expected app to show "${expectedText}"`);
});

Then('the todo is not in editing mode', function () {
  const items = this.document.querySelectorAll('.todo-list li');
  for (const item of items) {
    assert.ok(!item.classList.contains('editing'),
      'Expected no todo to be in editing mode');
  }
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  // Accept an optional localStorage payload to restore across reloads.
  async loadApp(seedData) {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // Capture localStorage before disposing the old window
    if (this.window && seedData === undefined) {
      try {
        var data = {};
        var k1 = this.window.localStorage.getItem('todos-vanilla');
        if (k1 !== null) data['todos-vanilla'] = k1;
        var k2 = this.window.localStorage.getItem('todos-vanilla-filter');
        if (k2 !== null) data['todos-vanilla-filter'] = k2;
        if (Object.keys(data).length > 0) seedData = data;
      } catch (e) { /* window already unusable */ }
    }
    // Dispose the previous window to free memory before creating a new one
    if (this.window) {
      await this.disposeApp();
    }

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // restore persisted data into the new window before evaling the app
    if (seedData !== undefined) {
      if (typeof seedData === 'string') {
        this.window.localStorage.setItem('todos-vanilla', seedData);
      } else {
        Object.keys(seedData).forEach(function(k) {
          this.window.localStorage.setItem(k, seedData[k]);
        }.bind(this));
      }
    }

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // Helper: create a todo by typing into the new-todo input and pressing Enter.
  _addTodo(title) {
    const input = this.document.querySelector('.new-todo');
    if (!input) throw new Error('new-todo input not found in _addTodo');
    input.value = title;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
      key: 'Enter', keyCode: 13, which: 13, bubbles: true
    }));
    input.dispatchEvent(new this.window.KeyboardEvent('keypress', {
      key: 'Enter', keyCode: 13, which: 13, bubbles: true
    }));
  }

  // Helper: click the toggle on the last todo to mark it complete.
  _completeLastTodo() {
    const items = this.document.querySelectorAll('.todo-list li');
    if (items.length === 0) throw new Error('No todos to complete in _completeLastTodo');
    const toggle = items[items.length - 1].querySelector('.toggle');
    if (!toggle) throw new Error('Toggle not found on last todo in _completeLastTodo');
    toggle.click();
  }

  // Helper: trigger a save. Dispatch a change that causes the app to persist.
  _triggerSave() {
    // Most TodoMVC apps save on every change via a state-change observer or
    // an event listener. If the app uses a custom save mechanism, a mutation
    // or storage event can trigger it. Dispatch the app's own save mechanism
    // or a storage event to force persistence.
    if (typeof this.window.saveTodos === 'function') {
      this.window.saveTodos();
    }
    // Fallback: trigger a storage event which some apps listen on.
    this.window.dispatchEvent(new this.window.StorageEvent('storage', {
      key: 'todos-vanilla', bubbles: true
    }));
  }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

